export function treeDemoLoadData(node: TreeItem | null): Promise<TreeLoadDataResult> {
  if (node === null) {
    return Promise.resolve({
      status: 'success',
      data: {
        list: [{ id: 'root', name: '\u6811\u9009\u9879' }]
      }
    })
  }

  const nodeId = String(node.id ?? '')

  if (nodeId === 'root') {
    return Promise.resolve({
      status: 'success',
      data: {
        list: [{ id: 'l1', name: '\u4E00\u7EA7\u6811\u7ED3\u6784', parentid: 'root' }]
      }
    })
  }

  if (nodeId === 'l1') {
    return Promise.resolve({
      status: 'success',
      data: {
        list: [{ id: 'l2', name: '\u4E8C\u7EA7\u6811\u7ED3\u6784', parentid: 'l1' }]
      }
    })
  }

  if (nodeId === 'l2') {
    return Promise.resolve({
      status: 'success',
      data: {
        list: [
          { id: 'a', name: 'A\u6587\u4EF6\u5939', parentid: 'l2', isLeaf: true },
          { id: 'b', name: 'B\u6587\u4EF6\u5939', parentid: 'l2', isLeaf: true }
        ]
      }
    })
  }

  return Promise.resolve({
    status: 'empty',
    data: { list: [] }
  })
}

export function treeDemoLoadSearchData(keyword: string): Promise<ListLoadResult> {
  const trimmed = keyword.trim()
  if (!trimmed) {
    return Promise.resolve({
      status: 'empty',
      data: { list: [] }
    })
  }

  const matches = [
    {
      id: 'a',
      name: 'A\u6587\u4EF6\u5939',
      path: [
        { id: 'root', name: '\u6811\u9009\u9879' },
        { id: 'l1', name: '\u4E00\u7EA7\u6811\u7ED3\u6784' },
        { id: 'l2', name: '\u4E8C\u7EA7\u6811\u7ED3\u6784' },
        { id: 'a', name: 'A\u6587\u4EF6\u5939' }
      ]
    },
    {
      id: 'b',
      name: 'B\u6587\u4EF6\u5939',
      path: [
        { id: 'root', name: '\u6811\u9009\u9879' },
        { id: 'l1', name: '\u4E00\u7EA7\u6811\u7ED3\u6784' },
        { id: 'l2', name: '\u4E8C\u7EA7\u6811\u7ED3\u6784' },
        { id: 'b', name: 'B\u6587\u4EF6\u5939' }
      ]
    }
  ].filter((row) => String(row.name).includes(trimmed))

  if (!matches.length) {
    return Promise.resolve({
      status: 'empty',
      data: { list: [] }
    })
  }

  return Promise.resolve({
    status: 'noMore',
    data: { list: matches }
  })
}
